<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="referrer" content="no-referrer"><title>Admit-card verification · ExamCell</title><x-assets /></head><body><main class="public-state"><x-card class="verification-card"><div class="card-body"><x-logo wordmark :size="40"/><p class="eyebrow verification-eyebrow">OFFICIAL ADMIT-CARD VERIFICATION</p><h1>{{ $valid?'Valid admit card':'Admit card is not currently valid' }}</h1><div class="verification-status"><x-badge :status="$valid?'Valid':'Invalid'"/></div><dl class="verification-details"><div><dt>Student name</dt><dd>{{ $studentName }}</dd></div><div><dt>Roll number</dt><dd>{{ $rollNumber }}</dd></div><div><dt>Examination</dt><dd>{{ $examName }}</dd></div><div><dt>Validity status</dt><dd>{{ $valid?'Valid':'Invalid' }}</dd></div></dl><p class="muted text-xs">{{ $valid?'This card matches an active, published examination record.':'This card does not currently meet the examination cell’s validity requirements. Contact the examination cell.' }}</p></div></x-card></main></body></html>
